flowchart TB
  subgraph R["受け取る部"]
    direction LR
    EB@{ svc: "Amazon EventBridge", label: "EventBridge<br/>event bus・<br/>別アカウント" }
    HE@{ svc: "AWS Health", label: "AWS Health<br/>対応と Region" }
    CT@{ svc: "AWS CloudTrail", label: "CloudTrail<br/>読み取りだけの<br/>管理イベント" }
    EB ~~~ HE ~~~ CT
  end
  subgraph P["処理する部"]
    direction LR
    DL["target に<br/>届かない時"]
    SN@{ svc: "Amazon SNS", label: "SNS<br/>fan out・<br/>filter policy" }
    RD@{ svc: "Amazon Kinesis Data Streams", label: "Kinesis・SQS<br/>読み手と Lambda" }
    SF@{ svc: "AWS Step Functions", label: "Pipes と<br/>Step Functions" }
    DL ~~~ SN ~~~ RD ~~~ SF
  end
  R ~~~ P

flowchart TB
  HE@{ svc: "AWS Health", label: "AWS Health<br/>のイベント" }
  RU@{ svc: "Amazon EventBridge", label: "EventBridge<br/>のルール" }
  AC["対応の例<br/>記録・通知・是正など"]
  HE -- "少なくとも 1 回" --> RU
  RU -- "当てはまれば" --> AC

flowchart TB
  subgraph R["受け取る部"]
    direction LR
    EB@{ svc: "Amazon EventBridge", label: "EventBridge<br/>受け取る側の<br/>bus に policy" }
    HE@{ svc: "AWS Health", label: "AWS Health<br/>Region と global" }
    CT@{ svc: "AWS CloudTrail", label: "CloudTrail<br/>有効だけでは<br/>読み取りを除く" }
    EB ~~~ HE ~~~ CT
  end
  subgraph P["処理する部"]
    direction LR
    DL["target に<br/>届かない時<br/>dead-letter queue"]
    SN@{ svc: "Amazon SNS", label: "SNS<br/>SQS へ fan out" }
    RD@{ svc: "Amazon Kinesis Data Streams", label: "Kinesis・SQS<br/>冪等に作る" }
    SF@{ svc: "AWS Step Functions", label: "Pipes は 1 対 1<br/>Step Functions<br/>は段" }
    DL ~~~ SN ~~~ RD ~~~ SF
  end
